def generate(root,web_pattern=None):
    for name,source in SOURCES.items():write(root/name,source)
    if web_pattern is not None:
        write(root/'android/util/Patterns.java','package android.util;public final class Patterns {public static final java.util.regex.Pattern WEB_URL=java.util.regex.Pattern.compile('+json.dumps(web_pattern,ensure_ascii=True)+');}\n')


